CREATE POLICY "Super admins upload global training videos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'training-videos' AND (storage.foldername(name))[1] = 'global' AND public.has_role(auth.uid(), 'super_admin'));
CREATE POLICY "Super admins update global training videos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'training-videos' AND (storage.foldername(name))[1] = 'global' AND public.has_role(auth.uid(), 'super_admin')) WITH CHECK (bucket_id = 'training-videos' AND (storage.foldername(name))[1] = 'global' AND public.has_role(auth.uid(), 'super_admin'));